import"./modulepreload-polyfill-Dezn_h7o.js";/* empty css               */import"./proteger-pagina-CCLhLS-N.js";import{t as e}from"./config-DPSuE5lU.js";document.querySelector(`#recuperar-form`).addEventListener(`submit`,async t=>{t.preventDefault();let n=document.querySelector(`#email`).value;try{let t=await fetch(`${e}/recuperar-senha`,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify({email:n})});if(t.ok)alert(`E-mail de recuperação enviado!`);else{let e=await t.json();alert(`Erro: ${e.message}`)}}catch{alert(`Erro ao conectar ao servidor.`)}});